const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const bytes=async b=>Array.from(new Uint8Array(await b.arrayBuffer())).join(',');



const attempt=fn=>{try{return fn()}catch(e){return e.name}};
const show=v=>typeof v==='string'?JSON.stringify(v):String(v);
const fields=(v,keys)=>keys.map(k=>k+':'+show(v[k])).join('|');
const dtTypes=d=>Array.from(d.types).join(',');
const readBlob=(blob,method='readAsText',encoding=undefined)=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r[method](blob,encoding)});
const stateLine=r=>[r.readyState,r.result,r.error?.name||''].join(':');
const options=name=>name==='PromiseRejectionEvent'?['synthetic',{promise:{}}]:name==='FormDataEvent'?['synthetic',{formData:new FormData()}]:name==='File'?[[],'synthetic.txt']:name==='Request'||name==='URL'?['https://app.example/']:name==='StaticRange'?[{startContainer:document.body,startOffset:0,endContainer:document.body,endOffset:0}]:name==='Touch'?[{identifier:1,target:document.body}]:name.endsWith('Event')?['synthetic']:[];
const probe=(name,kind=undefined)=>{const C=globalThis[name];if(typeof C!=='function'){log(name,'absent');return}const T=function(){};T.prototype=kind;let reads=0;const target=new Proxy(T,{get(t,k,r){if(k==='prototype')reads++;return Reflect.get(t,k,r)}});const value=Reflect.construct(C,options(name),target);log(name,C.name,Object.getPrototypeOf(value)===C.prototype,reads)};
